+        input.id = questionId + "-option-" + index;
+
+        label.htmlFor = input.id;
+        label.append(input, text);
+        return label;
+      };
+
+      const QuizQuestion = ({ id, prompt, helpText, options }) => {
+        const wrapper = createElement("div", "form-field");
+        const fieldset = document.createElement("fieldset");
+        const legend = createElement("legend", "", prompt);
+        const choiceList = createElement("div", "choices");
