+        if (helpText) {
+          const help = createElement("p", "help-text", helpText);
+          help.id = id + "-help";
+          fieldset.setAttribute("aria-describedby", help.id);
+          fieldset.append(legend, help);
+        } else {
+          fieldset.append(legend);
+        }
+
+        options.forEach((option, index) => {
+          choiceList.append(
+            AnswerOption({
+              questionId: id,
+              option,
+              index,
+            })
+          );
+        });
+
+        fieldset.append(choiceList);
+        wrapper.append(fieldset);
+        return wrapper;
+      };
+
+      const QuizForm = () => {
+        const form = document.createElement("form");
+        const result = createElement("div", "result");
+
+        form.noValidate = true;
+
