+
+        actions.append(submitButton, result);
+        form.append(actions);
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+
+          const totalSelections = quizQuestions.reduce((count, question) => {
+            return count + form.querySelectorAll('input[name="' + question.id + '"]:checked').length;
+          }, 0);
+
+          result.className = "result success";
+          result.textContent =
+            "Submitted. You selected " +
+            totalSelections +
+            " answer" +
+            (totalSelections === 1 ? "" : "s") +
+            " across 3 questions.";
+        });
+
+        return form;
+      };
